export function searchDocumentation(query: string): DocChapter[] {
  const terms = query.toLowerCase().trim().split(/\s+/).filter(Boolean);
  if (!terms.length) return documentation;
  return documentation.filter((chapter) => {
    const text = JSON.stringify(chapter).toLowerCase();
    return terms.every((term) => text.includes(term));
  });
}